import * as T from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {RoomEnvironment} from 'three/addons/environments/RoomEnvironment.js';
import {loadShapes,makeRobotRig,makeProduct,PRODUCT_NAMES} from './shapes.js';
const view=document.getElementById('view'),scene=new T.Scene(),camera=new T.PerspectiveCamera(38,1,.01,100),renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x14252e);renderer.toneMapping=T.ACESFilmicToneMapping;view.append(renderer.domElement);const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;
const env=new T.PMREMGenerator(renderer);scene.environment=env.fromScene(new RoomEnvironment(),.04).texture;scene.environmentIntensity=.6;scene.add(new T.HemisphereLight(0xffffff,0x698798,3));const light=new T.DirectionalLight(0xffffff,2);light.position.set(3,5,4);scene.add(light);scene.add(new T.GridHelper(5,20,0x4f7f87,0x2e4e59));let object,bounds;
function home(){const center=bounds.getCenter(new T.Vector3()),size=bounds.getSize(new T.Vector3()),r=Math.max(size.x,size.y,size.z);controls.target.copy(center);camera.position.copy(center).add(new T.Vector3(r*1.6,r*.9,r*1.7));controls.update();}
function show(){const key=document.getElementById('model').value;if(object)scene.remove(object);object=PRODUCT_NAMES[key]?makeProduct(key):makeRobotRig(key).root;scene.add(object);object.updateWorldMatrix(true,true);bounds=new T.Box3().setFromObject(object);home();const size=bounds.getSize(new T.Vector3());document.getElementById('status').textContent=key+' · 로드 완료';document.getElementById('detail').innerHTML=PRODUCT_NAMES[key]?`${PRODUCT_NAMES[key]} · 원본 메타팩토리 제품별 시각화 모델<br>실제 대상품의 CAD가 아닌 시연 모델입니다. 원본 치수 유지 · 폭/높이/깊이 ${(size.x*1000).toFixed(0)} / ${(size.y*1000).toFixed(0)} / ${(size.z*1000).toFixed(0)} mm`:`${key} · 제조사 공개 메시 + URDF 관절 구조 · 임의 확대 없음<br>마우스 드래그 회전 · 휠 확대. 형상 확인용 자세이며 충돌·가반하중 검증 결과를 의미하지 않습니다.<br><a href="${key.startsWith('HDR')?'https://github.com/hyundai-robotics/hdr_description':'https://github.com/DoosanRobotics/doosan-robot2'}" target="_blank" rel="noopener">제조사 원본</a> · <a href="assets/models/official/sources.json" target="_blank">사용 버전</a>`;}
document.getElementById('model').onchange=show;document.getElementById('home').onclick=home;new ResizeObserver(()=>{renderer.setSize(view.clientWidth,view.clientHeight);camera.aspect=view.clientWidth/view.clientHeight;camera.updateProjectionMatrix();}).observe(view);
try{await loadShapes();show();renderer.setAnimationLoop(()=>{controls.update();renderer.render(scene,camera);});}catch(e){document.getElementById('status').textContent='형상 로드 실패: '+e.message;console.error(e);}
